let settingsData=null,settingsWorkspace=null,settingsMode='profile',profileSettingsView='home',accountMoneyReturn='account',selectedSettingsRole='',selectedSettingsBusinessId=null,editingFinancialAccountId=null,accountStepUpState=null;
const stoken=()=>localStorage.getItem('abl_token')||'';
const sh=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const snice=v=>String(v||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const smoney=v=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(Number(v)||0);
const ROLE_LABELS={customer:'Customer',merchant:'Merchant',supplier:'Supplier',courier:'Delivery',service_provider:'Local Services'};
const BUSINESS_ROLES=new Set(['merchant','supplier']);
const SETTINGS_COMPATIBILITY_COPY=Object.freeze({drawer:'Account & profile settings',account_identity:'One external financial identity for this account',shared:'Shared across profiles',direct_payment:'Direct payment remains available even with Balance = 0',raw_card:'Raw card details are never stored here.',legacy_destination:'legacy profile financial destination'});
const ROLE_MONEY_COPY={
  customer:'Personal purchases, payments, refunds and optional personal money tracking. This is not business accounting.',
  merchant:'Business accounting, marketplace receipts, receivables, procurement payments and business payout settings.',
  supplier:'B2B Supplier income, Merchant receivables, production costs, fulfilment costs and payout settings.',
  courier:'Delivery earnings, pending/paid settlement, work expenses and payout destination.',
  service_provider:'Service-job income, receivables, work expenses and payout settings.'
};
const PROFILE_SETTINGS_COPY={
  customer:{title:'Customer settings',intro:'Personal shopping, delivery and privacy preferences for this Customer profile.',identity:'Customer identity and preferences'},
  merchant:{title:'Merchant settings',intro:'Business identity, operations and finance preferences for this Merchant workspace.',identity:'Business identity and workspace'},
  supplier:{title:'Supplier settings',intro:'Catalog, fulfilment and business preferences for this Supplier workspace.',identity:'Supplier identity and workspace'},
  courier:{title:'Delivery settings',intro:'Vehicle, availability, territory and earnings preferences for this Delivery profile.',identity:'Delivery identity and eligibility'},
  service_provider:{title:'Local Services settings',intro:'Public presentation, service area and work preferences for this Local Services profile.',identity:'Public service identity'}
};
async function sapi(path,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})};if(stoken())headers.Authorization='Bearer '+stoken();const r=await fetch(path,{cache:'no-store',...options,headers});const b=await r.json().catch(()=>({}));if(!r.ok)throw new Error(b.error||'Request failed ('+r.status+')');return b}
function stoast(msg){const t=document.getElementById('roleToast');if(t){t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000)}}
function ensureSettingsWorkspace(){const shell=document.getElementById('shell');if(!shell)return false;if(!document.getElementById('profileSettingsWorkspace')){settingsWorkspace=document.createElement('section');settingsWorkspace.id='profileSettingsWorkspace';settingsWorkspace.className='profileSettingsWorkspace hidden';shell.querySelector('.topbar')?.insertAdjacentElement('afterend',settingsWorkspace)}else settingsWorkspace=document.getElementById('profileSettingsWorkspace');return true}
function injectSettingsEntry(){const panel=document.getElementById('profileDrawerPanel');if(!panel||panel.querySelector('#profileSettingsButton'))return;const accountForm=panel.querySelector('#accountIdentityForm');const before=accountForm?.closest('.drawerSection')||null;const section=document.createElement('section');section.className='drawerSection';section.innerHTML='<h3>Settings</h3><button id="profileSettingsButton" class="settingsAvatarEntry" type="button"><span>⚙️</span><span><strong>Settings</strong><small>Payments, banking and profile preferences</small></span></button>';if(before)panel.insertBefore(section,before);else panel.appendChild(section);section.querySelector('#profileSettingsButton').onclick=openProfileSettings}
function hideSettingsBase(){document.querySelectorAll('#shell > .view').forEach(v=>v.classList.add('hidden'));document.querySelector('.bottomNav')?.classList.add('hidden');for(const id of ['roleHub','accountSettingsWorkspace','ordersWorkspace','marketWorkspace','servicesWorkspace','supWorkspace','deliveryWorkspace'])document.getElementById(id)?.classList.add('hidden');for(const id of ['basketBar','orderModalBackdrop','checkoutBackdrop','serviceModalBackdrop','supModalBg','deliveryModalBg'])document.getElementById(id)?.classList.add('hidden')}
function closeProfileSettings(){settingsWorkspace?.classList.add('hidden');profileSettingsView='home';window.BusinessLifeShell?.showActiveWorkspace?.()}
function selectedProfile(){return (settingsData?.profiles||[]).find(p=>p.role===selectedSettingsRole)||null}
function profileSettingsHeader(title,subtitle){return '<div class="settingsHeader"><button class="settingsBack" type="button" id="settingsBack" aria-label="Back">‹</button><div><h1>'+sh(title)+'</h1><p>'+sh(subtitle)+'</p></div></div>'}
function profileSettingsHome(){
  const profile=selectedProfile(),copy=PROFILE_SETTINGS_COPY[selectedSettingsRole]||{title:'Profile settings',intro:'Settings for this profile.',identity:'Profile identity'},business=businessForSettings();
  const identityName=BUSINESS_ROLES.has(selectedSettingsRole)?(business?.name||'Business workspace pending'):(ROLE_LABELS[selectedSettingsRole]+' profile');
  return profileSettingsHeader(copy.title,copy.intro)
    +'<section class="settingsHero settingsHeroSimple"><small>'+sh((ROLE_LABELS[selectedSettingsRole]||selectedSettingsRole).toUpperCase())+'</small><h2>'+sh(identityName)+'</h2><p>Profile ID: <strong>'+sh(profile?.profile_id||'Unavailable')+'</strong></p></section>'
    +'<div class="profileSettingsMenu">'
    +'<button type="button" data-profile-settings-view="identity"><span>🪪</span><span><strong>'+sh(copy.identity)+'</strong><small>View the identity and operating context owned by this profile.</small></span><b>›</b></button>'
    +'<button type="button" data-profile-settings-view="finance"><span>💳</span><span><strong>Money preferences</strong><small>Profile books, budgets, transfers and payout preferences.</small></span><b>›</b></button>'
    +'<button type="button" id="profileFinancialDocuments"><span>🧾</span><span><strong>Statements &amp; documents</strong><small>Open financial statements and traceable documents for this profile.</small></span><b>›</b></button>'
    +'<button type="button" id="profilePromotionCenter"><span>📣</span><span><strong>Promotion Center</strong><small>Referral and promotion tools attributed to this profile.</small></span><b>›</b></button>'
    +'<button type="button" data-profile-settings-view="status"><span>🧩</span><span><strong>Profile status</strong><small>Review lifecycle state or manage deactivation without changing your account.</small></span><b>›</b></button>'
    +'</div>';
}
function profileIdentitySettings(){
  const profile=selectedProfile(),business=businessForSettings(),copy=PROFILE_SETTINGS_COPY[selectedSettingsRole]||{};
  return profileSettingsHeader(copy.identity||'Profile identity','This information belongs to the selected profile, not to your personal account.')
    +'<section class="settingsCard"><div class="settingsSimpleRows"><div><span>Profile type</span><strong>'+sh(ROLE_LABELS[selectedSettingsRole]||selectedSettingsRole)+'</strong></div><div><span>Profile ID</span><strong>'+sh(profile?.profile_id||'Unavailable')+'</strong></div><div><span>Status</span><strong>'+sh(snice(profile?.status||(profile?.enabled?'active':'not_started')))+'</strong></div>'
    +(BUSINESS_ROLES.has(selectedSettingsRole)?'<div><span>Business workspace</span><strong>'+sh(business?.name||'Pending authorization')+'</strong></div>':'')+'</div>'
    +(BUSINESS_ROLES.has(selectedSettingsRole)?'<div class="settingsForm settingsBusinessPicker">'+businessSelector()+'</div>':'')+'</section>';
}
function profileStatusSettings(){
  const profile=selectedProfile();
  return profileSettingsHeader('Profile status','Lifecycle actions are managed separately from account identity and Admin authority.')
    +'<section class="settingsCard"><div class="settingsSimpleRows"><div><span>Profile</span><strong>'+sh(ROLE_LABELS[selectedSettingsRole]||selectedSettingsRole)+'</strong></div><div><span>Current state</span><strong>'+sh(snice(profile?.status||(profile?.enabled?'active':'not_started')))+'</strong></div><div><span>Profile ID</span><strong>'+sh(profile?.profile_id||'Unavailable')+'</strong></div></div><p>Disabling a profile preserves its ID, history and retained records. It does not delete your personal account or change Admin assignments.</p><button id="manageProfileLifecycle" class="settingsSecondary" type="button">Manage profile lifecycle</button></section>';
}
function businessForSettings(){return (settingsData?.businesses||[]).find(b=>Number(b.id)===Number(selectedSettingsBusinessId))||null}
function scopeAccounts(){return (settingsData?.financial_accounts||[]).filter(a=>a.profile_role===selectedSettingsRole&&(BUSINESS_ROLES.has(selectedSettingsRole)?Number(a.business_id)===Number(selectedSettingsBusinessId):a.business_id==null))}
function currentPreference(){return (settingsData?.preferences||[]).find(p=>p.profile_role===selectedSettingsRole&&(BUSINESS_ROLES.has(selectedSettingsRole)?Number(p.business_id)===Number(selectedSettingsBusinessId):p.business_id==null))||null}
function scopeBudgets(){return (settingsData?.budgets||[]).filter(b=>b.profile_role===selectedSettingsRole&&(BUSINESS_ROLES.has(selectedSettingsRole)?Number(b.business_id)===Number(selectedSettingsBusinessId):b.business_id==null))}
function activeBudgetOptions(selected=''){return '<option value="">Select budget</option>'+(settingsData?.budgets||[]).filter(b=>b.status==='active').map(b=>'<option value="'+b.id+'" '+(Number(b.id)===Number(selected)?'selected':'')+'>'+sh(ROLE_LABELS[b.profile_role]||snice(b.profile_role))+(b.business_id?' · business #'+sh(b.business_id):'')+' · '+sh(b.label)+' · '+smoney(b.allocated_budget)+'</option>').join('')}
function activeFinancialOptions(purpose){const rows=(settingsData?.financial_accounts||[]).filter(a=>a.status==='active'&&(purpose==='source'?(a.can_pay||['provider_clearing','paymongo_wallet'].includes(a.account_kind)):purpose==='payout'?a.can_payout:a.can_receive));return '<option value="">Select account</option>'+rows.map(a=>'<option value="'+a.id+'">'+sh(ROLE_LABELS[a.profile_role]||snice(a.profile_role))+(a.business_id?' · business #'+sh(a.business_id):'')+' · '+sh(a.display_name||snice(a.account_kind))+(a.reference_last4?' •••• '+sh(a.reference_last4):'')+'</option>').join('')}

function accountOptions(accounts,purpose,selected){const key=purpose==='receive'?'can_receive':purpose==='pay'?'can_pay':'can_payout';return '<option value="">Not selected</option>'+accounts.filter(a=>a.status==='active'&&a[key]).map(a=>'<option value="'+a.id+'" '+(Number(a.id)===Number(selected)?'selected':'')+'>'+sh(a.display_name||snice(a.account_kind))+(a.reference_last4?' •••• '+sh(a.reference_last4):'')+'</option>').join('')}
function accountMoneyIdentity(){return settingsData?.account_money?.identity||{}}
function accountMoneyDestinations(){return settingsData?.account_money?.destinations||[]}
function accountSavedMethods(){return settingsData?.account_money?.saved_payment_methods||[]}
function accountStepUpCard(){
  const verified=Boolean(accountStepUpState?.verified),minutes=Number(accountStepUpState?.valid_for_minutes||10);
  return '<div class="settingsNotice '+(verified?'ok':'')+'"><strong>'+(verified?'Identity confirmed for sensitive banking changes':'Confirm your identity for sensitive banking changes')+'</strong><br>'
    +(verified?'This session is cleared for payout-destination changes for up to '+minutes+' minutes.':'Payout-destination changes require recent authentication. Confirm your current password below. If you use Google without a local password, sign out and sign back in with Google to create a freshly verified session.')
    +'</div>'
    +(verified?'':'<form id="accountStepUpForm" class="settingsForm"><label>Current password<input id="accountStepUpPassword" type="password" autocomplete="current-password" maxlength="160" required></label><button class="settingsPrimary" type="submit">Confirm identity</button><div id="accountStepUpStatus" class="settingsStatus"></div></form>');
}
async function saveAccountStepUp(e){
  e.preventDefault();
  const out=document.getElementById('accountStepUpStatus'),input=document.getElementById('accountStepUpPassword');
  if(out)out.textContent='Confirming…';
  try{
    const result=await sapi('/api/auth/step-up/password',{method:'POST',body:JSON.stringify({password:input?.value||''})});
    if(input)input.value='';
    accountStepUpState=result;
    stoast('Identity confirmed for sensitive banking changes.');
    renderAccountMoneySettings();
  }catch(err){
    if(input)input.value='';
    if(out)out.textContent=err.message;
  }
}
async function refreshAccountStepUp(){
  try{accountStepUpState=await sapi('/api/auth/step-up/status')}
  catch{accountStepUpState={verified:false,valid_for_minutes:10}}
}
function accountMoneyDestinationCard(d){
  const cooling=Boolean(d.payout_cooling_off),eligible=d.payout_eligible_at?new Date(d.payout_eligible_at):null;
  const security=cooling&&eligible&&!Number.isNaN(eligible.getTime())
    ?'<span>Security hold until '+sh(eligible.toLocaleString())+'</span>'
    :d.can_payout?'<span>Payout security ready</span>':'';
  return '<article class="financialAccountCard"><div class="financialAccountTop"><div><strong>'+sh(d.display_name||snice(d.destination_kind))+'</strong><div>'+sh(d.institution_name||snice(d.destination_kind))+(d.reference_last4?' •••• '+sh(d.reference_last4):'')+'</div></div><span class="'+(d.verification_status==='verified'?'verified':d.verification_status==='rejected'?'rejected':'pending')+'">'+sh(snice(d.verification_status))+'</span></div>'
    +'<div class="financialAccountMeta"><span>'+sh(snice(d.destination_kind))+'</span><span>'+(d.is_default_payout?'Default payout':cooling?'24h security hold':'')+'</span><span>'+sh(d.currency_code||'PHP')+'</span>'+security+'</div>'
    +'<div class="financialAccountActions">'+(!d.is_default_payout&&d.status==='active'&&d.can_payout&&!cooling?'<button type="button" data-account-payout-default="'+d.id+'">Set default payout</button>':'')+(d.status==='active'?'<button type="button" data-account-destination-disable="'+d.id+'">Disable</button>':'')+'</div></article>';
}
function savedPaymentMethodCard(m){
  const label=m.display_label||[m.brand,m.last4?'•••• '+m.last4:''].filter(Boolean).join(' ')||snice(m.method_kind);
  return '<article class="financialAccountCard"><div class="financialAccountTop"><div><strong>'+sh(label)+'</strong><div>'+sh(m.provider_code||'Provider token')+(m.expiry_month&&m.expiry_year?' · expires '+String(m.expiry_month).padStart(2,'0')+'/'+m.expiry_year:'')+'</div></div><span class="'+(m.verification_status==='verified'?'verified':'pending')+'">'+sh(snice(m.verification_status))+'</span></div><div class="financialAccountMeta"><span>'+sh(snice(m.method_kind))+'</span><span>'+(m.is_default?'Default payment method':'')+'</span><span>Tokenized · raw card data not stored</span></div></article>';
}
function accountMoneySettingsCard(){return simpleMoneyBankingCard()}
async function saveAccountMoneyIdentity(e){e.preventDefault();const out=document.getElementById('accountMoneyIdentityStatus');out.textContent='Saving…';try{await sapi('/api/settings/account-money/identity',{method:'PUT',body:JSON.stringify({identity_kind:document.getElementById('accountIdentityKind').value,legal_name:document.getElementById('accountLegalName').value})});stoast('Financial identity saved.');await refreshSettings()}catch(err){out.textContent=err.message}}
async function saveAccountDestination(e){e.preventDefault();const out=document.getElementById('accountDestinationStatus');out.textContent='Saving…';try{await sapi('/api/settings/account-money/destinations',{method:'POST',body:JSON.stringify({destination_kind:document.getElementById('accountDestinationKind').value,display_name:document.getElementById('accountDestinationLabel').value,institution_name:document.getElementById('accountDestinationInstitution').value,account_name:document.getElementById('accountDestinationAccountName').value,reference_last4:document.getElementById('accountDestinationLast4').value,currency_code:'PHP',can_receive:true,can_payout:true})});stoast('Destination added. A 24-hour security hold applies before it can become the default payout.');await refreshSettings()}catch(err){out.textContent=err.message}}
async function disableAccountDestination(id){try{await sapi('/api/settings/account-money/destinations/'+id,{method:'PATCH',body:JSON.stringify({status:'inactive'})});stoast('Destination disabled.');await refreshSettings()}catch(err){stoast(err.message)}}
async function setDefaultAccountPayout(id){try{await sapi('/api/settings/account-money/destinations/'+id+'/default-payout',{method:'POST',body:'{}'});stoast('Default payout destination updated.');await refreshSettings()}catch(err){stoast(err.message)}}

function businessSelector(){if(!BUSINESS_ROLES.has(selectedSettingsRole))return'';const businesses=settingsData?.businesses||[];if(!businesses.length)return'<div class="settingsNotice">This profile does not yet have an approved economic/business workspace. Financial settings remain on HOLD until one exists.</div>';return '<label>Business workspace<select id="settingsBusinessSelect">'+businesses.map(b=>'<option value="'+b.id+'" '+(Number(b.id)===Number(selectedSettingsBusinessId)?'selected':'')+'>'+sh(b.name)+'</option>').join('')+'</select></label>'}
function accountCard(a){const verifyClass=a.verification_status==='verified'?'verified':a.verification_status==='pending'?'pending':'';return '<article class="financialAccountCard"><div class="financialAccountTop"><div><strong>'+sh(a.display_name||snice(a.account_kind))+'</strong><div>'+sh(a.institution_name||a.provider_code||snice(a.account_kind))+(a.reference_last4?' •••• '+sh(a.reference_last4):'')+'</div></div><span>'+sh(a.currency_code)+'</span></div><div class="financialAccountMeta"><span>'+sh(snice(a.account_kind))+'</span><span class="'+verifyClass+'">'+sh(snice(a.verification_status))+'</span>'+(a.can_pay?'<span>Pay</span>':'')+(a.can_receive?'<span>Receive</span>':'')+(a.can_payout?'<span>Payout</span>':'')+(a.provider_destination_configured?'<span>Provider ref linked</span>':'')+'</div><div class="financialAccountActions"><button class="settingsSecondary" type="button" data-fin-edit="'+a.id+'">Edit</button>'+(a.status==='active'?'<button class="settingsDanger" type="button" data-fin-disable="'+a.id+'">Deactivate</button>':'<button class="settingsSecondary" type="button" data-fin-enable="'+a.id+'">Reactivate</button>')+'</div></article>'}
function accountForm(existing=null){const a=existing||{};return '<form id="financialAccountForm" class="settingsForm"><h3>'+(existing?'Edit financial destination':'Add financial destination')+'</h3><p>This stores a safe reference used by your profile. Never paste a full bank/card number, PIN, password or CVV here.</p><div class="settingsGrid2"><label>Type<select id="finKind">'+(settingsData.catalog?.account_kinds||[]).map(k=>'<option value="'+k+'" '+(a.account_kind===k?'selected':'')+'>'+sh(snice(k))+'</option>').join('')+'</select></label><label>Display name<input id="finDisplay" maxlength="120" value="'+sh(a.display_name||'')+'" placeholder="Business bank / Personal e-wallet"></label></div><div class="settingsGrid2"><label>Institution / provider<input id="finInstitution" maxlength="120" value="'+sh(a.institution_name||'')+'" placeholder="Bank, PayMongo, GCash…"></label><label>Account holder name<input id="finAccountName" maxlength="160" value="'+sh(a.account_name||'')+'"></label></div><div class="settingsGrid2"><label>Last 4 only<input id="finLast4" maxlength="4" value="'+sh(a.reference_last4||'')+'" placeholder="1234"></label><label>Provider code<input id="finProvider" maxlength="80" value="'+sh(a.provider_code||'')+'" placeholder="paymongo"></label></div><label>Provider destination reference<input id="finProviderRef" maxlength="220" placeholder="'+(a.provider_destination_configured?'Leave blank to keep current provider reference':'Opaque provider destination ID — never account number')+'"></label><div class="settingsChecks"><label><input id="finPay" type="checkbox" '+(a.can_pay?'checked':'')+'> Pay from</label><label><input id="finReceive" type="checkbox" '+(a.can_receive?'checked':'')+'> Receive into</label><label><input id="finPayout" type="checkbox" '+(a.can_payout?'checked':'')+'> Payout to</label></div><div class="settingsGrid2"><button class="settingsPrimary" type="submit">'+(existing?'Save changes':'Add destination')+'</button>'+(existing?'<button id="cancelFinEdit" class="settingsSecondary" type="button">Cancel edit</button>':'')+'</div><div id="financialAccountStatus" class="settingsStatus"></div></form>'}
function budgetCard(b){return '<article class="budgetCard"><div class="financialAccountTop"><div><strong>'+sh(b.label)+'</strong><div>'+sh(snice(b.purpose))+' · '+sh(ROLE_LABELS[b.profile_role]||b.profile_role)+'</div></div><span>'+smoney(b.allocated_budget)+'</span></div><div class="budgetTruth"><strong>Allocated budget</strong><small>This is a planning allocation, not a provider-confirmed cash balance.</small></div>'+(b.linked_financial_account_id?'<div class="financialAccountMeta"><span>Linked: '+sh(b.linked_account_display_name||snice(b.linked_account_kind))+'</span><span>'+sh(snice(b.linked_account_verification_status||'unknown'))+'</span></div>':'<div class="financialAccountMeta"><span>No financial account linked</span></div>')+'<div class="financialAccountMeta"><span>Provider cash balance: unavailable without provider evidence</span></div></article>'}
function budgetForms(accounts,budgets){const purposes=settingsData.catalog?.budget_purposes||[],currentAccounts=accounts.filter(a=>a.status==='active');return '<div class="settingsSplit"><form id="budgetCreateForm" class="settingsForm"><h3>Create budget envelope</h3><p>Use separate envelopes for money planned for this activity. This does not create real money.</p><div class="settingsGrid2"><label>Budget label<input id="budgetLabel" maxlength="120" required placeholder="Supplier operating budget"></label><label>Purpose<select id="budgetPurpose">'+purposes.map(p=>'<option value="'+p+'">'+sh(snice(p))+'</option>').join('')+'</select></label></div><label>Optional linked financial account<select id="budgetLinkedAccount"><option value="">No linked account</option>'+currentAccounts.map(a=>'<option value="'+a.id+'">'+sh(a.display_name||snice(a.account_kind))+(a.reference_last4?' •••• '+sh(a.reference_last4):'')+'</option>').join('')+'</select></label><button class="settingsPrimary">Create budget</button><div id="budgetCreateStatus" class="settingsStatus"></div></form><form id="budgetAdjustForm" class="settingsForm"><h3>Allocate / reduce planned budget</h3><p>Changes the planning allocation only. It does not debit a bank or wallet.</p><label>Budget<select id="budgetAdjustEnvelope">'+(budgets.length?budgets.map(b=>'<option value="'+b.id+'">'+sh(b.label)+' · '+smoney(b.allocated_budget)+'</option>').join(''):'<option value="">No budget yet</option>')+'</select></label><div class="settingsGrid2"><label>Action<select id="budgetAdjustDirection"><option value="credit">Allocate more</option><option value="debit">Reduce allocation</option></select></label><label>Amount<input id="budgetAdjustAmount" type="number" min="0.01" step="0.01" required></label></div><label>Note<input id="budgetAdjustNote" maxlength="500" placeholder="Monthly allocation / reduce reserve…"></label><button class="settingsPrimary" '+(budgets.length?'':'disabled')+'>Save budget allocation</button><div id="budgetAdjustStatus" class="settingsStatus"></div></form></div>'}
function budgetTransferForm(){const active=(settingsData?.budgets||[]).filter(b=>b.status==='active');return '<form id="budgetTransferForm" class="settingsForm"><h3>Move allocated budget between profiles</h3><p>This is an internal budget reallocation. No bank/e-wallet/provider transfer occurs.</p><div class="settingsGrid2"><label>From<select id="budgetTransferFrom">'+activeBudgetOptions()+'</select></label><label>To<select id="budgetTransferTo">'+activeBudgetOptions()+'</select></label></div><div class="settingsGrid2"><label>Amount<input id="budgetTransferAmount" type="number" min="0.01" step="0.01" required></label><label>Note<input id="budgetTransferNote" maxlength="500" placeholder="Move reserve from Customer to Supplier…"></label></div><button class="settingsPrimary" '+(active.length>1?'':'disabled')+'>Reallocate budget</button><div id="budgetTransferStatus" class="settingsStatus"></div></form>'}
function fundScopeKey(s){return s.profile_role+'|'+String(s.business_id||0)}
function fundScopeLabel(s){return (ROLE_LABELS[s.profile_role]||snice(s.profile_role))+(s.business_id?' · '+(s.label||('Business #'+s.business_id)).replace(/ · (merchant|supplier)$/,''):'')+' · '+smoney(s.transferable_balance)}
function fundScopeOptions(){return '<option value="">Select profile</option>'+(settingsData?.profile_fund_scopes||[]).map(s=>'<option value="'+sh(fundScopeKey(s))+'">'+sh(fundScopeLabel(s))+'</option>').join('')}
function fundScopeFromKey(key){return (settingsData?.profile_fund_scopes||[]).find(s=>fundScopeKey(s)===key)||null}
function profileFundTransferForm(){
  const scopes=settingsData?.profile_fund_scopes||[],transfers=settingsData?.profile_fund_transfers||[];
  if(scopes.length<2)return '<div class="settingsNotice"><strong>Profile transfer</strong><br>Activate at least two profiles/workspaces to transfer funds between them.</div>';
  return '<form id="profileFundTransferForm" class="settingsForm"><h3>Transfer funds between my profiles</h3><p>Moves recorded funds only between your own active Business & Life profiles. No platform fee and no external bank/e-wallet transfer.</p><div class="settingsGrid2"><label>From<select id="profileFundFrom">'+fundScopeOptions()+'</select></label><label>To<select id="profileFundTo">'+fundScopeOptions()+'</select></label></div><div class="settingsGrid2"><label>Amount<input id="profileFundAmount" type="number" min="0.01" step="0.01" required></label><label>Note<input id="profileFundNote" maxlength="700" placeholder="Optional reason"></label></div><div id="profileFundSourceBalance" class="financeScopeNote">Choose a source profile to see its recorded balance.</div><button class="settingsPrimary" type="submit">Transfer between profiles</button><div id="profileFundStatus" class="settingsStatus"></div>'
    +(transfers.length?'<div class="movementHistory">'+transfers.slice(0,12).map(t=>'<div class="movementRow"><div><strong>'+sh(ROLE_LABELS[t.source_profile_role]||snice(t.source_profile_role))+' → '+sh(ROLE_LABELS[t.destination_profile_role]||snice(t.destination_profile_role))+'</strong><small>'+new Date(t.created_at).toLocaleDateString()+(t.note?' · '+sh(t.note):'')+'</small></div><span>'+smoney(t.amount)+'</span></div>').join('')+'</div>':'')
    +'</form>';
}
function syncProfileFundTransfer(){
  const from=document.getElementById('profileFundFrom'),to=document.getElementById('profileFundTo'),note=document.getElementById('profileFundSourceBalance');
  if(!from||!to)return;
  const src=fundScopeFromKey(from.value);
  for(const o of to.options)o.disabled=Boolean(from.value&&o.value===from.value);
  if(note)note.textContent=src?'Recorded transferable balance: '+smoney(src.transferable_balance)+' · provider balance is separate.':'Choose a source profile to see its recorded balance.';
}
async function saveProfileFundTransfer(e){
  e.preventDefault();const status=document.getElementById('profileFundStatus'),src=fundScopeFromKey(document.getElementById('profileFundFrom').value),dst=fundScopeFromKey(document.getElementById('profileFundTo').value);
  if(!src||!dst)return status.textContent='Choose two different profiles.';
  const amount=Number(document.getElementById('profileFundAmount').value);
  status.textContent='Transferring…';
  const key='profile-fund-'+Date.now()+'-'+Math.random().toString(16).slice(2);
  try{
    await sapi('/api/settings/profile-fund-transfers',{method:'POST',headers:{'Idempotency-Key':key},body:JSON.stringify({source_profile_role:src.profile_role,source_business_id:src.business_id,destination_profile_role:dst.profile_role,destination_business_id:dst.business_id,amount,currency_code:src.currency_code||'PHP',note:document.getElementById('profileFundNote').value})});
    stoast('Funds transferred between your profiles.');await refreshSettings();
  }catch(err){status.textContent=err.message}
}

function moneyMovementForm(){const movements=settingsData?.money_movements||[];return '<form id="moneyMovementForm" class="settingsForm"><h3>Real transfer / withdrawal request</h3><p>This creates a provider-neutral request only. It stays on HOLD until a verified adapter confirms real execution.</p><div class="settingsGrid2"><label>Type<select id="movementType"><option value="transfer">Transfer</option><option value="withdrawal">Withdrawal</option><option value="payout">Payout</option></select></label><label>Amount<input id="movementAmount" type="number" min="0.01" step="0.01" required></label></div><div class="settingsGrid2"><label>Source account<select id="movementSource">'+activeFinancialOptions('source')+'</select></label><label>Destination account<select id="movementDestination">'+activeFinancialOptions('receive')+'</select></label></div><label>Note<input id="movementNote" maxlength="500" placeholder="Reason / transfer purpose"></label><button class="settingsPrimary">Create HOLD request</button><div id="movementStatus" class="settingsStatus"></div>'+(movements.length?'<div class="movementHistory">'+movements.slice(0,12).map(m=>'<div class="movementRow"><div><strong>'+sh(snice(m.movement_type))+' · '+smoney(m.amount)+'</strong><small>'+sh(m.source_account_name||'Source')+' → '+sh(m.destination_account_name||'Destination')+'</small></div><span class="'+(m.status==='succeeded'?'verified':m.status==='pending_provider'?'pending':'')+'">'+sh(snice(m.status))+'</span></div>').join('')+'</div>':'<div class="settingsEmpty">No real money-movement requests yet.</div>')+'</form>'}

function preferencesForm(accounts){const p=currentPreference()||{};const methods=settingsData.catalog?.methods||[];const accepted=new Set(p.accepted_methods||[]);return '<form id="moneyPreferencesForm" class="settingsForm"><h3>Money defaults</h3><div class="settingsGrid2"><label>Default receive account<select id="prefReceive">'+accountOptions(accounts,'receive',p.default_receive_account_id)+'</select></label><label>Default pay-from account<select id="prefSpend">'+accountOptions(accounts,'pay',p.default_spend_account_id)+'</select></label></div><label>Default payout destination<select id="prefPayout">'+accountOptions(accounts,'payout',p.default_payout_account_id)+'</select></label><label>Payout schedule preference<select id="prefSchedule">'+(settingsData.catalog?.payout_schedules||[]).map(v=>'<option value="'+v+'" '+((p.payout_schedule_preference||'provider_default')===v?'selected':'')+'>'+sh(snice(v))+'</option>').join('')+'</select></label><div><strong>Accepted / used money methods</strong><div class="settingsMethodGrid">'+methods.map(m=>'<label><input type="checkbox" data-money-method="'+m+'" '+(accepted.has(m)?'checked':'')+'> '+sh(snice(m))+'</label>').join('')+'</div></div><button class="settingsPrimary">Save money preferences</button><div id="moneyPreferenceStatus" class="settingsStatus"></div></form>'}
function settingsRoleTitle(){return selectedSettingsRole==='customer'?'Customer settings':selectedSettingsRole==='merchant'?'Merchant settings':selectedSettingsRole==='supplier'?'Supplier settings':selectedSettingsRole==='courier'?'Delivery settings':'Local Services settings'}
function settingsRoleIntro(){
  if(selectedSettingsRole==='customer')return 'Keep payments simple: how you pay, what was refunded, and optional personal money tools.';
  if(selectedSettingsRole==='merchant')return 'Business banking and payout settings. Daily accounting stays in the Merchant Finance workspace.';
  if(selectedSettingsRole==='supplier')return 'Supplier banking and payout settings. PO income and receivables stay in Supplier Finance.';
  if(selectedSettingsRole==='courier')return 'Where delivery payouts should go. Earnings stay in Earnings & Money.';
  return 'Where service payouts should go. Job income stays in Money.';
}
