    +'<div class="sectionTitle"><h3>Add bank / e-wallet destination</h3></div><form id="accountDestinationForm" class="settingsForm"><div class="settingsGrid2"><label>Type<select id="accountDestinationKind"><option value="bank">Bank</option><option value="e_wallet">E-wallet</option><option value="paymongo_wallet">PayMongo Wallet</option><option value="other">Other</option></select></label><label>Label<input id="accountDestinationLabel" maxlength="120" required placeholder="Main payout account"></label><label>Institution / provider<input id="accountDestinationInstitution" maxlength="120" placeholder="Bank / GCash / Maya"></label><label>Account holder name<input id="accountDestinationAccountName" maxlength="160"></label><label>Last 4 only<input id="accountDestinationLast4" maxlength="4" placeholder="1234"></label></div><div class="settingsNotice"><strong>Do not enter a full account or card number, PIN, password or CVV.</strong></div><button class="settingsPrimary" type="submit">Add destination</button><div id="accountDestinationStatus" class="settingsStatus"></div></form>'
