    +'<section class="settingsCard settingsContextCard"><h2>'+sh(ROLE_LABELS[selectedSettingsRole]||selectedSettingsRole)+' profile</h2><div class="settingsScope"><div><strong>'+sh(BUSINESS_ROLES.has(selectedSettingsRole)?(business?.name||'Business workspace required'):'Personal profile')+'</strong><span>'+sh(BUSINESS_ROLES.has(selectedSettingsRole)?'Business books are kept separately':'No business books in this profile')+'</span></div></div>'+(BUSINESS_ROLES.has(selectedSettingsRole)?'<div class="settingsForm" style="margin-top:10px">'+businessSelector()+'</div>':'')+'</section>'
    +'<section class="settingsCard profileSettingsDestinations"><h2>Profile tools</h2><p>Tools in this section belong to the selected profile, not to your personal account.</p><div class="profileSettingsLinks"><button id="profilePromotionCenter" type="button">Promotion Center</button><button id="profileFinancialDocuments" type="button">Statements &amp; Documents</button></div></section>'
    +advancedProfileMoneyTools(accounts,budgets,provider,profileTransfer);
